function currentMessages(s){return s.messages.filter(m=>{if(!messageCurrent(s,m))return false;if(m.kind==='information')return false;if(m.kind==='request')return !m.resolvedBy;if(m.kind==='reply'){const q=s.messages.find(q=>q.teamId===m.teamId&&q.id===m.replyTo);if(q?.blockingAssignmentRevision){const t=s.teams.find(t=>t.id===m.teamId),a=currentAssignment(s,t,m.recipientId);if(!a||a.revision!==q.blockingAssignmentRevision||a.workStatus==='complete')return false;}}if(m.kind==='handoff'){const t=s.teams.find(t=>t.id===m.teamId),a=currentAssignment(s,t,m.recipientId);return !!a&&a.revision===m.assignmentRevision&&a.workStatus==='ready';}return s.attention.some(e=>{if(e.messageId!==m.id||e.teamId!==m.teamId||e.recipientId!==m.recipientId)return false;const p=s.sessions.find(p=>p.id===e.recipientId);return e.generation===s.generation&&(p.acknowledgment.generation!==s.generation||e.sequence>p.acknowledgment.throughSequence);});});}

